class TestProperties:
    """Property-based tests for statistical invariants."""

    def test_keyword_uniqueness(self, analyzer, sample_papers):
        """Test that extracted keywords are unique."""
        for paper in sample_papers:
            keywords = analyzer.extract_keywords(paper)
            assert len(keywords) == len(set(keywords))

    def test_classification_invariance(self, analyzer):
        """Test that classification is invariant to text case."""
        paper_upper = PaperMetadata(
            title="TEST",
            authors=["X"],
            abstract="TRANSFORMER ATTENTION DEEP LEARNING",
            year=2024,
            doi="doi",
            citations=100
        )
        paper_lower = PaperMetadata(
            title="test",
            authors=["x"],
            abstract="transformer attention deep learning",
            year=2024,
            doi="doi",
            citations=100
        )
        cat_upper = analyzer.classify_methodology(paper_upper)
        cat_lower = analyzer.classify_methodology(paper_lower)
        for category in cat_upper:
            assert abs(cat_upper[category] - cat_lower[category]) < 0.01

    def test_similarity_triangle_inequality(self, analyzer, sample_papers):
        """Test triangle inequality for similarity metric."""
        if len(sample_papers) >= 3:
            sim_ab = analyzer.compute_similarity(sample_papers[0], sample_papers[1])
            sim_bc = analyzer.compute_similarity(sample_papers[1], sample_papers[2])
            sim_ac = analyzer.compute_similarity(sample_papers[0], sample_papers[2])
            # Triangle inequality: sim_ac >= sim_ab + sim_bc - 1
            assert sim_ac >= sim_ab + sim_bc - 1.0


