class TestIntegration:
    """Integration tests with real dependencies."""

    def test_full_pipeline_integration(self, analyzer, sample_papers):
        """Test complete analysis pipeline end-to-end."""
        # Step 1: Extract keywords
        for paper in sample_papers:
            keywords = analyzer.extract_keywords(paper)
            assert len(keywords) > 0

        # Step 2: Classify methodology
        categories = analyzer.classify_methodology(sample_papers[0])
        assert len(categories) > 0

        # Step 3: Analyze citations
        citation_stats = analyzer.analyze_citations(sample_papers)
        assert citation_stats['total_citations'] > 0

        # Step 4: Detect trends
        trends = analyzer.detect_trends(sample_papers)
        assert len(trends['hot_topics']) > 0

        # Step 5: Compute similarities
        similarity_matrix = []
        for i in range(len(sample_papers)):
            row = []
            for j in range(len(sample_papers)):
                sim = analyzer.compute_similarity(sample_papers[i], sample_papers[j])
                row.append(sim)
            similarity_matrix.append(row)
        assert len(similarity_matrix) == len(sample_papers)

    def test_serialization_roundtrip(self, analyzer, sample_papers):
        """Test that analysis results can be serialized."""
        result = analyzer.analyze_paper(sample_papers[0])
        # Convert to dict for JSON serialization
        result_dict = {
            'keywords': result.keywords,
            'methodology_scores': result.methodology_scores,
            'citation_impact': result.citation_impact
        }
        json_str = json.dumps(result_dict)
        loaded = json.loads(json_str)
        assert loaded['keywords'] == result.keywords
        assert loaded['methodology_scores'] == result.methodology_scores
        assert loaded['citation_impact'] == result.citation_impact


